CREATE DATABASE IF NOT EXISTS startway CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE startway;
CREATE TABLE IF NOT EXISTS usuarios (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,tipo ENUM('jovem','empresa') NOT NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jovens (id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL UNIQUE,bio VARCHAR(500) NULL,cidade VARCHAR(120) NULL,formacao VARCHAR(180) NULL,linkedin VARCHAR(255) NULL,github VARCHAR(255) NULL,portfolio VARCHAR(255) NULL,data_nascimento DATE NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS empresas (id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL UNIQUE,nome_empresa VARCHAR(180) NOT NULL,cnpj CHAR(14) NOT NULL UNIQUE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vagas (id INT AUTO_INCREMENT PRIMARY KEY,empresa_id INT NOT NULL,titulo VARCHAR(180) NOT NULL,descricao TEXT NOT NULL,tipo VARCHAR(60) NOT NULL,modalidade VARCHAR(40) NOT NULL,cidade VARCHAR(120) NULL,salario DECIMAL(10,2) NULL,status VARCHAR(30) NOT NULL DEFAULT 'aberta',criada_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(empresa_id) REFERENCES empresas(id) ON DELETE CASCADE,INDEX idx_vagas_status_criada(status,criada_em));
CREATE TABLE IF NOT EXISTS candidaturas (id INT AUTO_INCREMENT PRIMARY KEY,vaga_id INT NOT NULL,jovem_id INT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'Em análise',data_candidatura DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_candidatura_vaga_jovem(vaga_id,jovem_id),FOREIGN KEY(vaga_id) REFERENCES vagas(id) ON DELETE CASCADE,FOREIGN KEY(jovem_id) REFERENCES jovens(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS habilidades (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS jovem_habilidades (id INT AUTO_INCREMENT PRIMARY KEY,jovem_id INT NOT NULL,habilidade_id INT NOT NULL,nivel VARCHAR(40) NULL,UNIQUE KEY uq_jovem_habilidade(jovem_id,habilidade_id),FOREIGN KEY(jovem_id) REFERENCES jovens(id) ON DELETE CASCADE,FOREIGN KEY(habilidade_id) REFERENCES habilidades(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cursos (id INT AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(180) NOT NULL,descricao TEXT NULL,plataforma VARCHAR(120) NULL,carga_horaria INT NULL,link VARCHAR(500) NULL,categoria VARCHAR(100) NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jovem_cursos (id INT AUTO_INCREMENT PRIMARY KEY,jovem_id INT NOT NULL,curso_id INT NOT NULL,progresso TINYINT UNSIGNED NOT NULL DEFAULT 0,concluido TINYINT(1) NOT NULL DEFAULT 0,data_conclusao DATETIME NULL,UNIQUE KEY uq_jovem_curso(jovem_id,curso_id),FOREIGN KEY(jovem_id) REFERENCES jovens(id) ON DELETE CASCADE,FOREIGN KEY(curso_id) REFERENCES cursos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vaga_habilidades (vaga_id INT NOT NULL,habilidade_id INT NOT NULL,PRIMARY KEY(vaga_id,habilidade_id),FOREIGN KEY(vaga_id) REFERENCES vagas(id) ON DELETE CASCADE,FOREIGN KEY(habilidade_id) REFERENCES habilidades(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recuperacao_senha (id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expira_em DATETIME NOT NULL,usado_em DATETIME NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tentativas_login (id INT AUTO_INCREMENT PRIMARY KEY,chave_hash CHAR(64) NOT NULL UNIQUE,tentativas INT NOT NULL DEFAULT 0,bloqueado_ate DATETIME NULL,atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
